var axios = require("axios");
export default {
  props: {
    finalPublishData: Array,
    previewPopup: Boolean,
    summaryField: String,
    apptype: String
  },
  components: {
    BarChart,
    ColoumnChart,
    PieChart,
    DonutChart,
    LineChart
  },
  data() {
    return {
      previewmodifiedarray: [],
      openedPanels: [],
      loading: false,
      componentKey: 0,
      activePanel: null
    };
  },
  watch: {
    previewPopup: {
      async handler() {
        this.previewmodifiedarray = await this.transformSectionData(this.finalPublishData);
        this.componentKey += 1;
        // console.log(this.previewmodifiedarray, "  this.previewmodifiedarray");
      },
      immediate: true
    }
  },
  methods: {
    getHeaderClass(panelIndex) {
      return this.activePanel === panelIndex ? false : true;
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    getRandomColor() {
      const letters = "0123456789ABCDEF";
      let color = "#";
      for (let i = 0; i < 6; i++) {
        color += letters[Math.floor(Math.random() * 16)];
      }
      return color;
    },
    publish_data() {
      this.loading = true;
      axios({
        method: "post",
        maxBodyLength: Infinity,
        url: this.$store.getters.GetOrgDetails.organization.invoke_url,
        headers: {
          "x-api-key": this.$store.getters.GetOrgDetails.organization["x-api-key"],
          "Content-Type": "application/json"
        },
        data: {
          tv_board_api_key: this.apptype == "TVBoard" ? this.$store.getters.GetTvdetails.tv_board_api_key : undefined,
          dashboard_api_key: this.apptype != "TVBoard" ? this.$store.getters.GetdashboardDetails.dashboard_api_key : undefined,
          section_data: this.finalPublishData,
          dashboard_summary: this.summaryField,
          team_api_key: this.$store.getters.GetOrgDetails.organization.team_api_key,
          content_type: "JSON",
          command: this.apptype == "TVBoard" ? "tvboardMessagePublish" : "dashboardMessagePublish"
        }
      }).then(res => {
        if (res.data.Status == "SUCCESS") {
          this.loading = false;
          this.$emit("successMsg", res.data.Message);
          // this.SnackBarComponent = {
          //   SnackbarVmodel: true,
          //   SnackbarColor: "green",
          //   SnackbarText: res.data.Message,
          //   timeout: 5000,
          //   Top: true,
          // };

          //   this.$refs.form.reset();
          //   this.editor8.setData("");
          // this.get_dashboard();
        } else {
          this.loading = false;
          this.$emit("erroMsg", res.data.Message);

          // this.SnackBarComponent = {
          //   SnackbarVmodel: true,
          //   SnackbarColor: "red",
          //   SnackbarText: res.data.Message,
          //   timeout: 5000,
          //   Top: true,
          // };
        }
      }).catch(err => {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: err.errors[0].message,
          timeout: 5000,
          Top: true
        };
      });
    },
    transformSectionData(lastdata) {
      return lastdata.map(section => {
        if (section.section_type === "PIE_CHART") {
          return {
            ...section,
            section_value: [{
              type: "pie",
              startAngle: 240,
              yValueFormatString: '##0.00"%"',
              indexLabel: "{label} {y}",
              dataPoints: section.section_value.map(item => ({
                y: Number(item.value),
                label: item.label
              }))
            }]
          };
        } else if (section.section_type === "DONUT_CHART") {
          return {
            ...section,
            section_value: [{
              type: "doughnut",
              startAngle: 60,
              indexLabelFontSize: 17,
              indexLabel: "{label} - #percent%",
              toolTipContent: "<b>{label}:</b> {y} (#percent%)",
              dataPoints: section.section_value.map(item => ({
                y: Number(item.value),
                label: item.label
              }))
            }]
          };
        }
        // else if (
        //   section.section_type === "BAR_CHART" ||
        //   section.section_type === "COLUMN_CHART"
        // ) {
        //   return {
        //     ...section,
